        BBwgFgAdIQgdIBcAHSQEHCQaAB0lBBwlGwAdJgQcJhwAHScEHCcdAB0pBBwpHwAeDwIeEAgAHhAEHRAHAB4RCB4QCAAeGAQdGA8A
        HhkEHRkQAB4aCB4ZEQAeHQQdHRQAHh4EHR4VAB4fBB0fFgAeIAQdIBcAHiEIHiAYAB4kBB0kGwAeJQQdJRwAHiYEHSYdAB4nBB0n
        HgAeKAgeJx8AHw4CHw8KAB8PAh8QCQAfEAQeEAgAHxEIHxAJAB8YBB4YEAAfGQQeGREAHxoIHxkSAB8bCB8aEwAfHAgfGxQAHx0I
        HxwVAB8eCB8dFgAfHwgfHhcAHyAIHx8YAB8hCB8gGQAfJAQeJBwAHyUEHiUdAB8mBB4mHgAfJwQeJx8AHygEHiggAB8pCB8oIQAg
        DgQfDgsAIBAEHxAJACARBB8RCgAgKAQfKCEAIQ4CIQ8MACEPAiEQCwAhEAQgEAoAIREEIBELACEoBCAoIgAiCwIiDBAAIgwCIg0P
        ACINAiIODgAiDgIiDw0AIg8CIhAMACIQBCEQCwAiEQQhEQwA
      ].join,
    }

    # Nexa Town, the town at the foot of the road: its eight exit tiles along the top edge.
    NEXA = 408
    NEXA_EXITS = [[18, 13], [19, 13], [20, 13], [21, 13], [22, 13], [23, 13], [24, 13], [25, 13]]

    WALK = 0
    SURF = 1
    DOOR = 2

    # Direction number => the word for it. 2 down, 4 left, 6 right, 8 up.
    DIR_KEY = { 8 => :dir_up, 2 => :dir_down, 4 => :dir_left, 6 => :dir_right }
    DELTA = { 8 => [0, -1], 2 => [0, 1], 4 => [-1, 0], 6 => [1, 0] }

    # {x * 1000 + y => [dir, kind, next x, next y, left]} for one map, or nil off the road.
    def self.table(mid)
      @tables ||= {}
      return @tables[mid] if @tables[mid]
      raw = RAW[mid]
      return nil if raw.nil?
      bytes = raw.unpack("m")[0]
      t = {}
      i = 0
      while i + 7 <= bytes.length
        x, y, dk, nx, ny, left = bytes[i, 7].unpack("CCCCCv")
        t[x * 1000 + y] = [dk & 15, dk >> 4, nx, ny, left]
        i += 7
      end
      @tables[mid] = t
    rescue StandardError
      nil
    end

    def self.here
      [($game_map.map_id rescue nil), ($game_player.x rescue 0), ($game_player.y rescue 0)]
    end

    def self.on_road?
      mid = ($game_map.map_id rescue nil)
      mid == NEXA || !RAW[mid].nil?
    rescue StandardError
      false
    end

    # From (px, py), every press in the same direction, merged by following each row's next-tile link.
    # Returns [presses, x, y] where x, y is the tile the leg ends on -- for a door, the door itself.
    def self.leg(t, px, py)
      r = t[px * 1000 + py]
      return [0, px, py] if r.nil?
      dir = r[0]
      n = 0
      x = px
      y = py
      guard = 0
      while r && r[0] == dir && r[1] != SURF && guard < 300
        guard += 1
        n += 1
        if r[1] == DOOR
          x += DELTA[dir][0]
          y += DELTA[dir][1]
          break
        end
        x = r[2]
        y = r[3]
        r = t[x * 1000 + y]
      end
      [n, x, y]
    end

    # The nearest tile the table knows, for when she is standing somewhere it does not.
    def self.nearest(t, px, py)
      best = nil
      bestd = nil
      t.each_key do |k|
        d = (k / 1000 - px).abs + (k % 1000 - py).abs
        if bestd.nil? || d < bestd
          bestd = d
          best = k
        end
      end
      best.nil? ? nil : [best / 1000, best % 1000, bestd]
    end

    def self.dir_word(d)
      PokeAccess::I18n.t(DIR_KEY[d] || :dir_up)
    end

    # The next instruction. The walkthrough asks for it every frame, so it is worked out once per tile.
    def self.steps
      h = here
      return @steps_val if @steps_key == h && @steps_val
      @steps_key = h
      @steps_val = compute_steps(h[0], h[1], h[2])
    rescue StandardError
      []
    end

    def self.compute_steps(mid, px, py)
      t = table(mid)
      return [] if t.nil?
      r = t[px * 1000 + py]
      if r.nil?
        near = nearest(t, px, py)
        return [] if near.nil?
        return [PokeAccess::I18n.t(:vr_offroad,
                                   :where => PokeAccess::I18n.t(:laser_at, :x => near[0].to_s,
                                                                :y => near[1].to_s),
                                   :n => near[2].to_s)]
      end
      if r[1] == SURF
        return [PokeAccess::I18n.t(:vr_surf, :dir => dir_word(r[0]), :left => r[4].to_s)]
      end
      [PokeAccess::I18n.t(:vr_leg, :n => leg(t, px, py)[0].to_s, :dir => dir_word(r[0]),
                          :left => r[4].to_s)]
    rescue StandardError
      []
    end

    # What the scanner points at: the END OF THE LEG she is on, never the League itself -- the router
    # cannot model a slide, so a faraway goal on an ice floor would have it plan a walk the game will not
    # allow. In Nexa Town it is the nearest exit onto the road; a surf launch points at the water.
    def self.targets
      mid, px, py = here
      spot = nil
      if mid == NEXA
        bestd = nil
        NEXA_EXITS.each do |x, y|
          d = (x - px).abs + (y - py).abs
          if bestd.nil? || d < bestd
            bestd = d
            spot = [x, y]
          end
        end
      else
        t = table(mid)
        return [] if t.nil?
        r = t[px * 1000 + py]
        if r.nil?
          near = nearest(t, px, py)
          spot = near ? [near[0], near[1]] : nil
        elsif r[1] == SURF
          spot = [px + DELTA[r[0]][0], py + DELTA[r[0]][1]]
        else
          l = leg(t, px, py)
          spot = [l[1], l[2]]
        end
      end
      return [] if spot.nil?
      [PokeAccess::Locator::SurfaceTarget.new(spot[0], spot[1], PokeAccess::I18n.t(:vr_target), :league)]
    rescue StandardError
      []
    end
  end
end

PokeAccess::Game.define("insurgence") do
  PokeAccess::InsurgenceVictoryRoad::RAW.keys.each do |mid|
    puzzle(mid,
      :kind        => :walkthrough,
      :walkthrough => lambda { PokeAccess::InsurgenceVictoryRoad.steps })
  end
end

PokeAccess::Locator.register_category(:league,
  :label     => :tcat_league,
  :available => lambda { PokeAccess::InsurgenceVictoryRoad.on_road? },
  :targets   => lambda { PokeAccess::InsurgenceVictoryRoad.targets })
